public int maxSubsetSum(int[] a) {
    return f(a, 0);
}

private int f(int[] a, int i) {
    if (i >= a.length) return 0;
    int take = a[i] + f(a, i + 2);
    int skip = f(a, i + 1);
    return Math.max(take, skip);
}

