public int maxSubsetSum(int[] a) {
    Integer[] memo = new Integer[a.length];
    return f(a, 0, memo);
}

private int f(int[] a, int i, Integer[] memo) {
    if (i >= a.length) return 0;
    if (memo[i] != null) return memo[i];
    int take = a[i] + f(a, i + 2, memo);
    int skip = f(a, i + 1, memo);
    return memo[i] = Math.max(take, skip);
}

