def max_subset_sum(self, a: list[int]) -> int:
    n = len(a)
    if n == 1:
        return a[0]
    dp: list[int] = [0] * n
    dp[0] = a[0]
    dp[1] = max(a[0], a[1])
    for i in range(2, n):
        dp[i] = max(dp[i - 1], dp[i - 2] + a[i], a[i])
    return dp[n - 1]

