public int maxSubsetSum(int[] a) {
    int prev2 = 0;
    int prev1 = a[0];
    for (int i = 1; i < a.length; i++) {
        int cur = Math.max(prev1, Math.max(prev2 + a[i], a[i]));
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

